LABELS={'candidata':'Candidata técnica','adaptador':'Necesita adaptador','revisar':'Requiere corrección/revisión','restricciones':'Con restricciones','sin-concluir':'Sin conclusión de acceso'}

def a(url,label):
    return f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label)}</a>'

def main():
    audit=json.loads(AUDIT.read_text(encoding='utf-8')); heads=json.loads(HEADS.read_text(encoding='utf-8'))
    sites=audit['sites']; assert {s['id'] for s in sites}==set(REVIEWS), 'Review coverage must be exact'
    for s in sites:
        assessment,rights,note,evidence=REVIEWS[s['id']]
        s.update(assessment=assessment,rights=rights,note=note,policy_evidence=evidence)
    entries=sites+[dict(s,samples=[],samples_attempted=0,candidate_complete_samples=0,selected_in_mesa=False,documentary_only=True) for s in DOC_SITES]
    stats={'sites_probed':len(sites),'documentary_assessments':len(DOC_SITES),'evaluated_entries':len(entries),'candidate_urls_in_final_sample':sum(len(s['samples']) for s in sites),
           'parser_returned_fields':sum(p.get('mesa_server_parser',{}).get('ok',False) for s in sites for p in s['samples']),
           'numeric_photo_candidates':sum(bool(p.get('candidate_complete')) for s in sites for p in s['samples']),
           'photo_head_checks':len(heads['image_heads']),'image_head_200':sum(p.get('status')==200 and p.get('content_type','').startswith('image/') for p in heads['image_heads'])}
    conclusions={'checked_at':datetime.now(timezone.utc).isoformat(),'application_version':'1.9.1+18','application_changed':False,
                 'retained_catalogue_sources':16,'stats':stats,'rankings':[
                  {'region':'Worldwide','period':'2026-09','url':'https://www.similarweb.com/top-websites/food-and-drink/cooking-and-recipes/','top5':['allrecipes.com','cookpad.com','delishkitchen.tv','kurashiru.com','giallozafferano.it']},
                  {'region':'Spain','period':'2026-09','url':'https://www.similarweb.com/top-websites/spain/food-and-drink/cooking-and-recipes/','top5':['cookpad.com','cookidoo.es','recetasparathermomix.com','velocidadcuchara.com','amimaneracocinando.com']},
                  {'region':'Mexico','period':'2026-09','url':'https://www.similarweb.com/top-websites/mexico/food-and-drink/cooking-and-recipes/','top5':['recetasnestle.com.mx','kiwilimon.com','cookpad.com','directoalpaladar.com.mx','cocinavital.mx']}],
                 'method':audit['method'],'sources':entries,'apis':APIS,
                 'important_limits':['Convenience sample, not a census or an acceptance test of an entire catalogue.',
                   'Generic Python server parser differs from registered Dart direct-client adapters.',
                   'Recipe fields, numeric tokens and image URLs do not prove correct quantities, complete galleries or reuse rights.',
                   'No new sources activated, no translation engine implemented, no new APK built.',
                   'No photo bodies downloaded, no credentials, accounts, paywall bypasses, publisher messages or catalogue downloads.']}
    out=ROOT/'output/importable-sites-conclusions-2026-10-11.json'
    out.write_text(json.dumps(conclusions,ensure_ascii=False,indent=2),encoding='utf-8')
    rows=[]
    for s in entries:
        evidence=s.get('policy_evidence') or s.get('evidence')
        samples=[]
        for p in s['samples']:
            parsed=p.get('mesa_server_parser',{})
            url=p.get('final_url') or p['url']
            if parsed.get('ok'):
                summary=f"{parsed['ingredients']} filas · {parsed['steps']} pasos · {parsed['photo_urls']} URL de fotos · {parsed['ingredient_rows_with_number']} filas con cifras"
            else:
                summary=p.get('error') or parsed.get('error') or p.get('robots',{}).get('decision','No consultada')
            samples.append('<li>'+a(url,parsed.get('title') or 'Página examinada')+'<br><span class="muted">'+escape(summary)+'</span></li>')
        detail=('<details><summary>Ver evidencia y limitaciones</summary><p>'+escape(s['note'])+'</p>'
                +(('<p>'+a(evidence,'Referencia de la revisión')+'</p>') if evidence else '')
                +('<ul class="samples">'+''.join(samples)+'</ul>' if samples else '<p>Revisión documental; sin receta completa probada.</p>')+'</details>')
        measured='Documental' if s.get('documentary_only') else f"{s['candidate_complete_samples']}/{s['samples_attempted']} candidatas"
        active='En las 16 fuentes' if s['selected_in_mesa'] else 'No activada'
        rows.append(f'<tr data-lang="{s["language"]}" data-state="{s["assessment"]}" data-name="{escape(s["name"].casefold(),quote=True)}"><td><strong>{a(s["url"],s["name"])}</strong><span class="muted">{escape(active)}</span></td><td>{escape(s["language"].upper())}</td><td><span class="badge {s["assessment"]}">{LABELS[s["assessment"]]}</span><span class="muted">{measured}</span></td><td>{escape(s["rights"])}</td><td>{detail}</td></tr>')
    apirows=''.join('<tr><td>'+a(x['url'],x['name'])+'</td><td>'+escape(x['verdict'])+'</td><td>'+escape(x['note'])+'</td></tr>' for x in APIS)
    rankings=''.join('<li>'+a(x['url'],{'Worldwide':'Mundial','Spain':'España','Mexico':'México'}[x['region']])+' · septiembre 2026: '+escape(', '.join(x['top5']))+'</li>' for x in conclusions['rankings'])
